/* CEO scenario: independent from patient registry and actual financial inputs. */
state.quarterScenario??=JSON.parse(JSON.stringify(quarterlyExample));let financeDisplay='quarterly',clinicalDisplay='quarterly';
const financialBeforeQuarter=financialView,clinicalBeforeQuarter=clinicalQualityView;
const moneyQ=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:0});const percentQ=n=>n===null?'—':n.toFixed(1)+'%';
function quarterBanner(){return `<div class="notice"><b>HYPOTHETICAL BUSINESS CASE — ALL VALUES ARE INVENTED.</b> Q2 → Q3 2026 represents an assumed July rollout, not this application's actual deployment. Latest two completed quarters are used; Q4 is incomplete. These are separate modeled cohorts, not results derived from the 200-patient registry or evidence that CDS caused improvement.</div>`}
function scenarioActions(mode){return `<div class="actions" style="margin:0"><button class="btn" onclick="editQuarterScenario()">Model assumptions</button><button class="btn" onclick="exportQuarterScenario()">Export scenario</button><button class="btn" onclick="openCEOReport('${mode==='financial'?'financial':'clinical'}')">Print CEO view</button><button class="btn" onclick="${mode==='financial'?"financeDisplay='manual'":"clinicalDisplay='episodes'"};render()">${mode==='financial'?'Manual financial inputs':'Current episode audit'}</button></div>`}
financialView=function(){if(financeDisplay==='manual')return `<button class="btn" onclick="financeDisplay='quarterly';render()">← Quarterly CEO scenario</button>`+financialBeforeQuarter();const s=state.quarterScenario,m=calculateQuarter(s);return header('Financial impact · CEO scenario','Hypothetical investment case with traceable claims, revenue and cost arithmetic.',scenarioActions('financial'))+quarterBanner()+`<div class="quarterperiod"><b>${esc(s.baseline)}</b><span>BEFORE ASSUMED CDS → AFTER ASSUMED CDS</span><b>${esc(s.followup)}</b></div><div class="cards"><div class="card"><small>FIRST-PASS NON-ACCEPTANCE</small><b class="number">${percentQ(m.beforeRate)} → ${percentQ(m.afterRate)}</b><p>${m.beforeRejected}/${s.claims} → ${m.afterRejected}/${s.claims} claims · ${m.rateReductionPP.toFixed(1)} pp lower</p></div><div class="card"><small>MODELED COLLECTIBLE REVENUE UPLIFT</small><b class="number">+${moneyQ(m.uplift)}</b><p>${percentQ(m.revenueGrowth)} · ${esc(s.currency)} · same billing volume/value</p></div><div class="card"><small>FIRST POST-QUARTER NET BENEFIT</small><b class="number">${moneyQ(m.net)}</b><p>After ${moneyQ(m.cost)} implementation + operating cost</p></div><div class="card"><small>MODELED ROI / PAYBACK</small><b class="number">${percentQ(m.roi)}</b><p>${m.paybackMonths===null?'No modeled payback':m.paybackMonths.toFixed(2)+' months modeled payback'} · ${percentQ(s.realization*100)} assumed uplift realization</p></div></div><section class="panel"><h2>What changed in claims?</h2><p>Each claim has one mutually exclusive primary reason. Technical rejection is a pre-adjudication validation return; adjudicated denial follows payer review. Combined first-pass non-acceptance is the headline, not technical rejection alone.</p><div class="scroll"><table><thead><tr><th>Primary reason / stage</th><th>Q2 count / rate</th><th>Q3 count / rate</th><th>Relative reduction</th><th>Assumed workflow contribution</th></tr></thead><tbody>${s.reasons.map(r=>`<tr><td><b>${esc(r.name)}</b><div class="mini">${esc(r.stage)}</div></td><td>${r.before} / ${percentQ(100*r.before/s.claims)}</td><td>${r.after} / ${percentQ(100*r.after/s.claims)}</td><td>${r.before?percentQ(100*(r.before-r.after)/r.before):'—'}</td><td>${esc(r.mechanism)}</td></tr>`).join('')}<tr><td><b>TOTAL combined non-acceptance</b></td><td>${m.beforeRejected} / ${percentQ(m.beforeRate)}</td><td>${m.afterRejected} / ${percentQ(m.afterRate)}</td><td>${percentQ(m.relativeReduction)}</td><td>Bundled CDS + administrative workflow scenario, not CDS-only proof</td></tr></tbody></table></div><p>Technical rejections: ${m.technicalBefore} → ${m.technicalAfter}. Adjudicated denials: ${m.denialsBefore} → ${m.denialsAfter}. Counts are unique submissions, not repeat rejections of the same claim.</p><button class="btn" onclick="downloadQuarterClaims()">Download 2,000 synthetic claim records (CSV)</button></section><div class="grid2" style="margin-top:20px"><section class="panel"><h2>Revenue bridge · ${esc(s.currency)}</h2><table><thead><tr><th>Item</th><th>Q2 model</th><th>Q3 model</th></tr></thead><tbody><tr><td>Gross billed (${s.claims} × ${moneyQ(s.claimValue)})</td><td>${moneyQ(m.grossBilled)}</td><td>${moneyQ(m.grossBilled)}</td></tr><tr><td>Initially non-accepted claim value</td><td>${moneyQ(m.rejectedValueBefore)}</td><td>${moneyQ(m.rejectedValueAfter)}</td></tr><tr><td>Modeled later recovery (${percentQ(s.recoveryFraction*100)})</td><td>${moneyQ(m.modeledRecoveryBefore)}</td><td>${moneyQ(m.modeledRecoveryAfter)}</td></tr><tr><td><b>Modeled eventual collectible revenue</b></td><td><b>${moneyQ(m.revenueBefore)}</b></td><td><b>${moneyQ(m.revenueAfter)}</b></td></tr></tbody></table><p>Not actual period cash collections. Equal recovery assumptions and fixed volume/price isolate an illustrative rejection effect. Lower rejected value is not added again as revenue. Accepted claims are assumed fully collectible at the entered value; contractual discounts, tax, financing and implementation disruption are not modeled.</p></section><section class="panel"><h2>Investment & break-even</h2><div class="stage">One-time build / implementation: <b>${moneyQ(s.upfront)}</b></div><div class="stage">Quarterly operating cost: <b>${moneyQ(s.quarterOperating)}</b></div><div class="stage">Assumed realized uplift: <b>${moneyQ(m.realized)}</b></div><div class="stage">First post-quarter net: <b>${moneyQ(m.net)}</b> · ROI ${percentQ(m.roi)}</div><div class="stage">Recurring quarter net (no repeat build cost): <b>${moneyQ(m.recurringNet)}</b></div><p>First-quarter break-even requires ${m.breakEvenRealization===null?'positive incremental revenue':percentQ(m.breakEvenRealization)+' realization of the modeled uplift'}. Payback assumes even monthly uplift/operating cost and upfront build payment; it is a scenario, not a guarantee.</p></section></div><section class="panel" style="margin-top:20px"><h2>Clinical resource capacity · excluded from cash ROI</h2><p>${m.bedDaysReleased} fewer modeled inpatient bed-days × ${moneyQ(s.variableBedDay)} variable resource value = <b>${moneyQ(m.bedResourceValue)}</b>. ${m.beforeRejected-m.afterRejected} fewer non-accepted claims × ${moneyQ(s.reworkPerClaim)} rework value = <b>${moneyQ(m.reworkResourceValue)}</b>.</p><p>Total capacity/resource value: <b>${moneyQ(m.capacityValue)} ${esc(s.currency)}</b>. These are not guaranteed cash savings and are not added to the revenue/ROI headline. Sepsis, ICU and LOS benefits overlap; no separate sepsis/ICU cost is added.</p></section><section class="panel" style="margin-top:20px"><h2>Sensitivity: what if less benefit is realized?</h2><table><thead><tr><th>Realized share of modeled uplift</th><th>Incremental revenue</th><th>First-quarter net</th><th>ROI</th></tr></thead><tbody>${[.25,.5,1].map(f=>{const x=calculateQuarter({...s,realization:f});return `<tr><td>${percentQ(f*100)}</td><td>${moneyQ(x.realized)}</td><td>${moneyQ(x.net)}</td><td>${percentQ(x.roi)}</td></tr>`}).join('')}</tbody></table><p>Realization captures the assumed fraction captured in practice. Attribution to CDS remains unproven even at 100%. A real evaluation needs matched definitions, comparable case/payer mix and a credible comparison design.</p></section>`};
clinicalQualityView=function(){if(clinicalDisplay==='episodes')return `<button class="btn" onclick="clinicalDisplay='quarterly';render()">← Quarterly clinical scenario</button>`+clinicalBeforeQuarter();const s=state.quarterScenario,m=calculateQuarter(s),pick=k=>m.clinical.find(x=>x.key===k),ant=pick('antibiotic'),sepsis=pick('sepsis'),icu=pick('icu');return header('Clinical impact · quarterly scenario','Before/after rates with explicit denominators and outcome definitions.',scenarioActions('clinical'))+quarterBanner()+`<div class="quarterperiod"><b>${esc(s.baseline)}</b><span>200 ELIGIBLE FN EPISODES IN EACH HYPOTHETICAL QUARTER</span><b>${esc(s.followup)}</b></div><div class="cards"><div class="card"><small>APPROPRIATE ANTIBIOTIC ≤60 MIN</small><b class="number">${percentQ(ant.beforeRate)} → ${percentQ(ant.afterRate)}</b><p>${ant.before}/${ant.denom} → ${ant.after}/${ant.denom} · +${ant.changePP.toFixed(1)} pp</p></div><div class="card"><small>NEW / WORSENING SEPSIS</small><b class="number">${percentQ(sepsis.beforeRate)} → ${percentQ(sepsis.afterRate)}</b><p>${sepsis.before} → ${sepsis.after} episodes · ${percentQ(-sepsis.relativeChange)} relative reduction</p></div><div class="card"><small>UNPLANNED ICU TRANSFER</small><b class="number">${percentQ(icu.beforeRate)} → ${percentQ(icu.afterRate)}</b><p>${icu.before} → ${icu.after} episodes · ${percentQ(-icu.relativeChange)} relative reduction</p></div><div class="card"><small>INPATIENT LENGTH OF STAY</small><b class="number">${m.losBefore.toFixed(1)} → ${m.losAfter.toFixed(1)} d</b><p>${s.bedDaysBefore} → ${s.bedDaysAfter} bed-days / ${s.inpatients} admissions</p></div></div><section class="panel"><h2>Process & outcome scorecard</h2><p>Same hypothetical eligibility rules, 200 adult FN episodes, ${s.inpatients} admissions and ${s.discharged} discharges in each period. Illustrative case mix: 120 high-risk and 80 low-risk episodes; 20 low-risk episodes also admitted. This is not the current registry's measured case mix.</p><div class="scroll"><table><thead><tr><th>Measure</th><th>Baseline Q2</th><th>Post Q3</th><th>Change (post − pre)</th><th>Interpretation</th></tr></thead><tbody>${m.clinical.map(r=>`<tr><td><b>${esc(r.label)}</b><details><summary>Definition</summary><p>${esc(r.definition)}</p></details></td><td>${r.before}/${r.denom}<div class="mini">${percentQ(r.beforeRate)}</div></td><td>${r.after}/${r.denom}<div class="mini">${percentQ(r.afterRate)}</div></td><td>${r.changePP>0?'+':''}${r.changePP.toFixed(1)} pp</td><td>${r.higher?'Higher is the desired direction':'Lower is the desired direction'}<div class="mini">Relative change ${r.relativeChange===null?'—':(r.relativeChange>0?'+':'')+percentQ(r.relativeChange)}</div></td></tr>`).join('')}</tbody></table></div></section><div class="grid2" style="margin-top:20px"><section class="panel"><h2>How the scenario might work</h2><p>Structured assessment and visible risk → earlier clinician review → source-linked draft orders and administration tracking → fewer missed steps → planned reassessment and follow-up. Clinical outcome reductions are hypothetical assumptions, not predictions from these process changes.</p><p>Antibiotic-delay episodes: ${s.cohort-ant.before} → ${s.cohort-ant.after}. Sepsis outcome is not generated by MASCC or lactate alone. Improved detection can initially increase recorded sepsis even when care improves.</p></section><section class="panel"><h2>What a real CEO claim would require</h2><p>Real quarter-level numerator/denominator data; equivalent observation windows; validated sepsis definitions; complete 30-day follow-up; standardized appropriateness review; case-mix/payer adjustment; enough observations; and assessment of concurrent changes and uncertainty.</p><p>Mortality changes here are 8 vs 6 invented events; no statistical significance, causality or expected treatment effect is asserted. Q3 30-day outcomes are fictional complete follow-up, not observed data.</p><button class="btn" onclick="clinicalDisplay='episodes';render()">Open actual demo episode audit</button></section></div>`};
function editQuarterScenario(){const s=state.quarterScenario;openDialog('Quarterly scenario assumptions',`<p>All quarter data remain fictional. These controls test whether the business case remains positive under different assumptions.</p><form onsubmit="event.preventDefault();saveQuarterScenario(this)"><div class="grid2">${[['upfront','One-time implementation cost',s.upfront],['quarterOperating','Quarter operating cost',s.quarterOperating],['claimValue','Average value per claim',s.claimValue],['realization','Realized share of uplift (%)',s.realization*100],['recoveryFraction','Later recovery of non-accepted value (%)',s.recoveryFraction*100],['variableBedDay','Variable resource value per bed-day',s.variableBedDay],['reworkPerClaim','Resource value per returned claim',s.reworkPerClaim]].map(([k,l,v])=>`<label class="field">${l}<input type="number" name="${k}" min="0" ${['realization','recoveryFraction'].includes(k)?'max="100"':''} value="${v}" step="any" required></label>`).join('')}</div><p id="quarterError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Recalculate scenario</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`);document.querySelector('#workflowDialog').classList.add('assessmentdialog')}
function saveQuarterScenario(form){try{const f=new FormData(form),s={...state.quarterScenario};for(const k of ['upfront','quarterOperating','claimValue','variableBedDay','reworkPerClaim'])s[k]=Number(f.get(k));s.realization=Number(f.get('realization'))/100;s.recoveryFraction=Number(f.get('recoveryFraction'))/100;validateQuarter(s);state.quarterScenario=s;closeDialog();save('Updated hypothetical quarter scenario assumptions; not measured outcomes')}catch(e){document.querySelector('#quarterError').textContent=e.message}}
function exportQuarterScenario(){download('FN_CEO_HYPOTHETICAL_quarters.json',{label:'ALL DATA INVENTED — NOT OBSERVED OR CAUSAL EVIDENCE',inputs:state.quarterScenario,calculations:calculateQuarter(state.quarterScenario),independentOfPatientRegistry:true});save('Exported labelled hypothetical quarterly scenario')}
function downloadQuarterClaims(){const rows=syntheticClaims(state.quarterScenario),headers=Object.keys(rows[0]),quote=v=>'"'+String(v).replaceAll('"','""')+'"',csv=[headers.join(','),...rows.map(r=>headers.map(k=>quote(r[k])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='HYPOTHETICAL_FN_claims_Q2_Q3_2026.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);save('Exported 2000 invented claim rows; projected amounts, not actual collections')}
